class LRUCacheBrute:
    def __init__(self, capacity):
        self.capacity = capacity
        self.entries = []          # list of [key, value, timestamp]
        self.clock = 0

    def get(self, key):
        for entry in self.entries:
            if entry[0] == key:                        # linear scan for the key
                self.clock += 1
                entry[2] = self.clock
                return entry[1]
        return -1

    def put(self, key, value):
        self.clock += 1
        for entry in self.entries:
            if entry[0] == key:
                entry[1] = value
                entry[2] = self.clock
                return
        if len(self.entries) >= self.capacity:
            oldest_idx = min(range(len(self.entries)), key=lambda i: self.entries[i][2])  # scan for LRU
            self.entries.pop(oldest_idx)
        self.entries.append([key, value, self.clock])

