import java.util.*;

class LRUCacheBrute {
    int capacity, clock = 0;
    List<int[]> entries = new ArrayList<>();   // [key, value, timestamp]

    LRUCacheBrute(int capacity) { this.capacity = capacity; }

    int get(int key) {
        clock++;
        for (int[] e : entries) {
            if (e[0] == key) { e[2] = clock; return e[1]; }    // linear scan for the key
        }
        return -1;
    }

    void put(int key, int value) {
        clock++;
        for (int[] e : entries) {
            if (e[0] == key) { e[1] = value; e[2] = clock; return; }
        }
        if (entries.size() >= capacity) {
            int oldestIdx = 0;
            for (int i = 1; i < entries.size(); i++)
                if (entries.get(i)[2] < entries.get(oldestIdx)[2]) oldestIdx = i;  // scan for LRU
            entries.remove(oldestIdx);
        }
        entries.add(new int[]{key, value, clock});
    }
}

