    void put(int key, int value) {
        clock++;
        for (auto& e : entries) {
            if (e[0] == key) { e[1] = value; e[2] = clock; return; }
        }
        if ((int)entries.size() >= capacity) {
            int oldestIdx = 0;
            for (int i = 1; i < (int)entries.size(); i++)
                if (entries[i][2] < entries[oldestIdx][2]) oldestIdx = i;   // scan for LRU
            entries.erase(entries.begin() + oldestIdx);
        }
        entries.push_back({key, value, clock});
    }
