struct Node { int key, val; Node* prev; Node* next; Node(int k, int v) : key(k), val(v), prev(nullptr), next(nullptr) {} };

class LRUCache {
public:
    int capacity;
    unordered_map<int, Node*> map;
    Node *head, *tail;                                          // dummy sentinels

    LRUCache(int cap) : capacity(cap) {
        head = new Node(0, 0); tail = new Node(0, 0);
        head->next = tail; tail->prev = head;
    }

    void remove(Node* node) { node->prev->next = node->next; node->next->prev = node->prev; }
    void insertFront(Node* node) {
        node->next = head->next; node->prev = head;
        head->next->prev = node; head->next = node;
    }

    int get(int key) {
        if (!map.count(key)) return -1;
        Node* node = map[key];
        remove(node);
        insertFront(node);                                        // mark as most recently used
        return node->val;
    }

    void put(int key, int value) {
        if (map.count(key)) {
            remove(map[key]);
        } else if ((int)map.size() >= capacity) {
            Node* lru = tail->prev;                                // least recently used, at the tail
            remove(lru);
            map.erase(lru->key);
        }
        Node* node = new Node(key, value);
        map[key] = node;
        insertFront(node);
    }
};
